Šta se ispisuje?

static void M(ref string s1, string s2)
{
    s1 += "312";
    s2 += "321";
}
public static void Main()
{
    string s1 = "456";
    string s2 = s1;
    s2 = "654";
    string s3 = (s1 == s2 || s1[1] != s2[1]) ? s1 : s2;
    M(ref s3, s1);
    Console.WriteLine(s3[^1]);
}

Šta se ispisuje?

static void M(ref string s1, string s2)
{
    s1 += "321"; s2 += "123";
}
public static void Main()
{
    string s1 = "456"; string s2 = "654"; s2 = s1;
    string s3 = (s1 == s2) ? s2 : s1;
    M(ref s3, s1);
    string s4 = (s3[0] != s1[0] ? s3 : s1);
    Console.WriteLine(s4[^3]);
}

