program Test;
var a: integer;

procedure Povecaj;
begin
    a := a + 1;
end;

procedure Print;
begin
    a := a + 2; write(a);
end;

procedure Prva;
begin
    a := a + 3; Povecaj; Print;
end;

procedure Druga;
var a: integer;
begin
    a := 4; Povecaj; Print;
end;

begin
    a := 2; Povecaj; Prva; Print; Druga; Print;
end.

